import { Blog, BlogStatus, Role } from '@prisma/client';
import prisma from '../db';
import { BadRequestError, ForbiddenError, NotFoundError } from '../utils/AppError';

/**
 * 创建博客输入接口
 */
export interface CreateBlogInput {
  title: string;
  content: string;
  excerpt?: string | null;
  coverImage?: string | null;
  categoryId?: number | null;
  tagIds?: number[];
  status?: BlogStatus;
  authorId: number;
}

/**
 * 更新博客输入接口
 */
export interface UpdateBlogInput {
  title?: string;
  content?: string;
  excerpt?: string | null;
  coverImage?: string | null;
  categoryId?: number | null;
  tagIds?: number[] | null;
  status?: BlogStatus;
}

/**
 * 博客查询参数接口
 */
export interface GetBlogsParams {
  page?: number;
  limit?: number;
  status?: BlogStatus;
  authorId?: number;
  categoryId?: number;
  tagId?: number;
  search?: string;
  sortBy?: 'createdAt' | 'updatedAt' | 'publishedAt' | 'viewCount';
  sortOrder?: 'asc' | 'desc';
}

/**
 * 博客列表返回接口
 */
export interface PaginatedBlogs {
  blogs: any[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

/**
 * 创建博客文章
 */
export const createBlog = async (input: CreateBlogInput) => {
  const {
    title,
    content,
    excerpt,
    coverImage,
    categoryId,
    tagIds,
    status = BlogStatus.DRAFT,
    authorId,
  } = input;

  // 验证分类是否存在（如果提供了分类ID）
  if (categoryId) {
    const category = await prisma.category.findUnique({
      where: { id: categoryId },
    });
    if (!category) {
      throw new BadRequestError('指定的分类不存在');
    }
  }

  // 验证标签是否存在（如果提供了标签ID）
  if (tagIds && tagIds.length > 0) {
    const tags = await prisma.tag.findMany({
      where: { id: { in: tagIds } },
    });
    if (tags.length !== tagIds.length) {
      throw new BadRequestError('部分标签不存在');
    }
  }

  // 创建博客
  const blog = await prisma.blog.create({
    data: {
      title,
      content,
      excerpt,
      coverImage,
      status,
      authorId,
      categoryId,
      // 创建博客标签关联
      ...(tagIds && tagIds.length > 0 && {
        blogTags: {
          create: tagIds.map(tagId => ({ tagId })),
        },
      }),
    },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
        },
      },
      category: {
        select: {
          id: true,
          name: true,
          slug: true,
        },
      },
      blogTags: {
        include: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
    },
  });

  // 格式化返回数据
  return {
    ...blog,
    tags: blog.blogTags.map(blogTag => blogTag.tag),
    blogTags: undefined,
  };
};

/**
 * 根据ID获取博客详情
 */
export const getBlogById = async (blogId: number, increaseViewCount: boolean = false) => {
  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
          bio: true,
        },
      },
      category: {
        select: {
          id: true,
          name: true,
          slug: true,
          description: true,
        },
      },
      blogTags: {
        include: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
      _count: {
        select: {
          comments: true,
          likes: true,
          bookmarks: true,
        },
      },
    },
  });

  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  // 如果需要增加浏览次数
  if (increaseViewCount && blog.status === BlogStatus.PUBLISHED) {
    await prisma.blog.update({
      where: { id: blogId },
      data: { viewCount: { increment: 1 } },
    });
    blog.viewCount += 1;
  }

  // 格式化返回数据
  const formattedBlog = {
    ...blog,
    tags: blog.blogTags.map(blogTag => blogTag.tag),
    blogTags: undefined,
  };

  return formattedBlog;
};

/**
 * 检查用户是否有权操作博客（作者或管理员）
 */
const checkBlogPermission = async (blogId: number, userId: number, userRole: Role) => {
  if (userRole === Role.ADMIN) {
    return true;
  }

  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
    select: { authorId: true },
  });

  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  if (blog.authorId !== userId) {
    throw new ForbiddenError('您没有权限操作此博客');
  }

  return true;
};

/**
 * 更新博客文章
 */
export const updateBlog = async (
  blogId: number,
  input: UpdateBlogInput,
  userId: number,
  userRole: Role
) => {
  // 检查权限
  await checkBlogPermission(blogId, userId, userRole);

  const { tagIds, ...updateData } = input;

  // 验证分类是否存在（如果提供了分类ID）
  if (updateData.categoryId !== undefined) {
    if (updateData.categoryId === null) {
      // 允许设置为null
    } else {
      const category = await prisma.category.findUnique({
        where: { id: updateData.categoryId },
      });
      if (!category) {
        throw new BadRequestError('指定的分类不存在');
      }
    }
  }

  // 开始事务，更新博客和标签关联
  const updatedBlog = await prisma.$transaction(async (tx) => {
    // 更新博客基本信息
    const blog = await tx.blog.update({
      where: { id: blogId },
      data: {
        ...updateData,
        // 如果提供了状态且是发布状态，设置发布时间
        ...(updateData.status === BlogStatus.PUBLISHED && {
          publishedAt: new Date(),
        }),
      },
      include: {
        author: {
          select: {
            id: true,
            name: true,
            email: true,
            avatar: true,
          },
        },
        category: {
          select: {
            id: true,
            name: true,
            slug: true,
          },
        },
        blogTags: {
          include: {
            tag: {
              select: {
                id: true,
                name: true,
                slug: true,
              },
            },
          },
        },
      },
    });

    // 如果提供了tagIds，更新标签关联
    if (tagIds !== undefined) {
      // 删除现有的标签关联
      await tx.blogTag.deleteMany({
        where: { blogId },
      });

      // 创建新的标签关联（如果tagIds不为null且不为空）
      if (tagIds && tagIds.length > 0) {
        // 验证标签是否存在
        const tags = await tx.tag.findMany({
          where: { id: { in: tagIds } },
        });
        if (tags.length !== tagIds.length) {
          throw new BadRequestError('部分标签不存在');
        }

        // 创建新的关联
        await tx.blogTag.createMany({
          data: tagIds.map(tagId => ({ blogId, tagId })),
        });

        // 重新获取更新后的标签关联
        const updatedBlogTags = await tx.blogTag.findMany({
          where: { blogId },
          include: {
            tag: {
              select: {
                id: true,
                name: true,
                slug: true,
              },
            },
          },
        });
        blog.blogTags = updatedBlogTags;
      } else {
        // tagIds为空数组，表示清空所有标签
        blog.blogTags = [];
      }
    }

    return blog;
  });

  // 格式化返回数据
  return {
    ...updatedBlog,
    tags: updatedBlog.blogTags.map(blogTag => blogTag.tag),
    blogTags: undefined,
  };
};

/**
 * 删除博客文章（软删除：标记为DELETED状态）
 */
export const deleteBlog = async (blogId: number, userId: number, userRole: Role) => {
  // 检查权限
  await checkBlogPermission(blogId, userId, userRole);

  // 软删除：将状态标记为DELETED
  const deletedBlog = await prisma.blog.update({
    where: { id: blogId },
    data: { status: BlogStatus.DELETED },
    select: {
      id: true,
      title: true,
      status: true,
    },
  });

  return {
    message: '博客已成功删除',
    blog: deletedBlog,
  };
};

/**
 * 发布博客文章
 */
export const publishBlog = async (blogId: number, userId: number, userRole: Role) => {
  // 检查权限
  await checkBlogPermission(blogId, userId, userRole);

  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
    select: { status: true },
  });

  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  if (blog.status === BlogStatus.PUBLISHED) {
    throw new BadRequestError('博客已经是发布状态');
  }

  if (blog.status === BlogStatus.DELETED) {
    throw new BadRequestError('已删除的博客不能发布');
  }

  const publishedBlog = await prisma.blog.update({
    where: { id: blogId },
    data: {
      status: BlogStatus.PUBLISHED,
      publishedAt: new Date(),
    },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
        },
      },
      category: {
        select: {
          id: true,
          name: true,
          slug: true,
        },
      },
      blogTags: {
        include: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
    },
  });

  // 格式化返回数据
  return {
    ...publishedBlog,
    tags: publishedBlog.blogTags.map(blogTag => blogTag.tag),
    blogTags: undefined,
  };
};

/**
 * 获取博客列表（支持分页和筛选）
 */
export const getBlogs = async (params: GetBlogsParams): Promise<PaginatedBlogs> => {
  const {
    page = 1,
    limit = 10,
    status,
    authorId,
    categoryId,
    tagId,
    search,
    sortBy = 'createdAt',
    sortOrder = 'desc',
  } = params;

  // 构建查询条件
  const where: any = {};

  // 状态筛选（默认排除已删除的博客）
  if (status) {
    where.status = status;
  } else {
    where.status = { not: BlogStatus.DELETED };
  }

  // 作者筛选
  if (authorId) {
    where.authorId = authorId;
  }

  // 分类筛选
  if (categoryId) {
    where.categoryId = categoryId;
  }

  // 标签筛选（通过关联表）
  if (tagId) {
    where.blogTags = {
      some: { tagId },
    };
  }

  // 搜索条件（标题或内容包含关键词）
  if (search) {
    where.OR = [
      { title: { contains: search, mode: 'insensitive' } },
      { content: { contains: search, mode: 'insensitive' } },
      { excerpt: { contains: search, mode: 'insensitive' } },
    ];
  }

  // 计算总数
  const total = await prisma.blog.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 获取博客列表
  const blogs = await prisma.blog.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: {
      [sortBy]: sortOrder,
    },
    include: {
      author: {
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
        },
      },
      category: {
        select: {
          id: true,
          name: true,
          slug: true,
        },
      },
      blogTags: {
        include: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
      _count: {
        select: {
          comments: true,
          likes: true,
          bookmarks: true,
        },
      },
    },
  });

  // 格式化博客数据
  const formattedBlogs = blogs.map(blog => ({
    ...blog,
    tags: blog.blogTags.map(blogTag => blogTag.tag),
    blogTags: undefined,
  }));

  return {
    blogs: formattedBlogs,
    pagination: {
      page,
      limit,
      total,
      totalPages,
    },
  };
};

/**
 * 获取指定用户的博客列表
 */
export const getUserBlogs = async (userId: number, params: GetBlogsParams) => {
  return getBlogs({
    ...params,
    authorId: userId,
  });
};

/**
 * 按分类获取博客列表
 */
export const getBlogsByCategory = async (categoryId: number, params: GetBlogsParams) => {
  // 验证分类是否存在
  const category = await prisma.category.findUnique({
    where: { id: categoryId },
  });
  if (!category) {
    throw new NotFoundError('分类不存在');
  }

  return getBlogs({
    ...params,
    categoryId,
  });
};

/**
 * 按标签获取博客列表
 */
export const getBlogsByTag = async (tagId: number, params: GetBlogsParams) => {
  // 验证标签是否存在
  const tag = await prisma.tag.findUnique({
    where: { id: tagId },
  });
  if (!tag) {
    throw new NotFoundError('标签不存在');
  }

  return getBlogs({
    ...params,
    tagId,
  });
};

