import { Request, Response } from 'express';
import asyncHandler from '../utils/asyncHandler';
import * as blogService from '../services/blog.service';
import { AuthenticatedRequest } from '../middleware/auth';
import { Role } from '@prisma/client';

/**
 * 创建博客文章
 */
export const createBlog = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要登录才能创建博客',
    });
  }

  const {
    title,
    content,
    excerpt,
    coverImage,
    categoryId,
    tagIds,
    status,
  } = req.body;

  const blog = await blogService.createBlog({
    title,
    content,
    excerpt,
    coverImage,
    categoryId: categoryId ? parseInt(categoryId) : null,
    tagIds: tagIds ? tagIds.map((id: any) => parseInt(id)) : undefined,
    status,
    authorId: req.user.userId,
  });

  res.status(201).json({
    success: true,
    data: blog,
  });
});

/**
 * 获取单个博客详情
 */
export const getBlog = asyncHandler(async (req: Request, res: Response) => {
  const blogId = parseInt(req.params.id);
  if (isNaN(blogId)) {
    return res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
  }

  // 对于获取博客详情，增加浏览次数
  const increaseViewCount = true;
  const blog = await blogService.getBlogById(blogId, increaseViewCount);

  res.status(200).json({
    success: true,
    data: blog,
  });
});

/**
 * 获取博客列表
 */
export const getBlogs = asyncHandler(async (req: Request, res: Response) => {
  const {
    page = '1',
    limit = '10',
    status,
    authorId,
    categoryId,
    tagId,
    search,
    sortBy,
    sortOrder,
  } = req.query;

  const params: blogService.GetBlogsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    status: status as blogService.BlogStatus,
    authorId: authorId ? parseInt(authorId as string) : undefined,
    categoryId: categoryId ? parseInt(categoryId as string) : undefined,
    tagId: tagId ? parseInt(tagId as string) : undefined,
    search: search as string,
    sortBy: sortBy as any,
    sortOrder: sortOrder as any,
  };

  const result = await blogService.getBlogs(params);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 更新博客文章
 */
export const updateBlog = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const blogId = parseInt(req.params.id);
  if (isNaN(blogId)) {
    return res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
  }

  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要登录才能更新博客',
    });
  }

  const {
    title,
    content,
    excerpt,
    coverImage,
    categoryId,
    tagIds,
    status,
  } = req.body;

  const updateData: blogService.UpdateBlogInput = {};
  if (title !== undefined) updateData.title = title;
  if (content !== undefined) updateData.content = content;
  if (excerpt !== undefined) updateData.excerpt = excerpt;
  if (coverImage !== undefined) updateData.coverImage = coverImage;
  if (categoryId !== undefined) {
    updateData.categoryId = categoryId === null ? null : parseInt(categoryId);
  }
  if (tagIds !== undefined) {
    updateData.tagIds = tagIds === null ? null : tagIds.map((id: any) => parseInt(id));
  }
  if (status !== undefined) updateData.status = status;

  const updatedBlog = await blogService.updateBlog(
    blogId,
    updateData,
    req.user.userId,
    req.user.role as Role
  );

  res.status(200).json({
    success: true,
    data: updatedBlog,
  });
});

/**
 * 删除博客文章
 */
export const deleteBlog = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const blogId = parseInt(req.params.id);
  if (isNaN(blogId)) {
    return res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
  }

  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要登录才能删除博客',
    });
  }

  const result = await blogService.deleteBlog(
    blogId,
    req.user.userId,
    req.user.role as Role
  );

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 发布博客文章
 */
export const publishBlog = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const blogId = parseInt(req.params.id);
  if (isNaN(blogId)) {
    return res.status(400).json({
      success: false,
      error: '无效的博客ID',
    });
  }

  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要登录才能发布博客',
    });
  }

  const publishedBlog = await blogService.publishBlog(
    blogId,
    req.user.userId,
    req.user.role as Role
  );

  res.status(200).json({
    success: true,
    data: publishedBlog,
  });
});

/**
 * 获取当前用户的博客列表
 */
export const getUserBlogs = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) {
    return res.status(400).json({
      success: false,
      error: '无效的用户ID',
    });
  }

  // 检查权限：用户只能查看自己的博客，管理员可以查看任何用户的博客
  if (req.user?.role !== Role.ADMIN && req.user?.userId !== userId) {
    return res.status(403).json({
      success: false,
      error: '您只能查看自己的博客',
    });
  }

  const {
    page = '1',
    limit = '10',
    status,
    categoryId,
    tagId,
    search,
    sortBy,
    sortOrder,
  } = req.query;

  const params: blogService.GetBlogsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    status: status as blogService.BlogStatus,
    authorId: userId,
    categoryId: categoryId ? parseInt(categoryId as string) : undefined,
    tagId: tagId ? parseInt(tagId as string) : undefined,
    search: search as string,
    sortBy: sortBy as any,
    sortOrder: sortOrder as any,
  };

  const result = await blogService.getUserBlogs(userId, params);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 按分类获取博客列表
 */
export const getBlogsByCategory = asyncHandler(async (req: Request, res: Response) => {
  const categoryId = parseInt(req.params.categoryId);
  if (isNaN(categoryId)) {
    return res.status(400).json({
      success: false,
      error: '无效的分类ID',
    });
  }

  const {
    page = '1',
    limit = '10',
    status,
    authorId,
    tagId,
    search,
    sortBy,
    sortOrder,
  } = req.query;

  const params: blogService.GetBlogsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    status: status as blogService.BlogStatus,
    authorId: authorId ? parseInt(authorId as string) : undefined,
    categoryId,
    tagId: tagId ? parseInt(tagId as string) : undefined,
    search: search as string,
    sortBy: sortBy as any,
    sortOrder: sortOrder as any,
  };

  const result = await blogService.getBlogsByCategory(categoryId, params);

  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 按标签获取博客列表
 */
export const getBlogsByTag = asyncHandler(async (req: Request, res: Response) => {
  const tagId = parseInt(req.params.tagId);
  if (isNaN(tagId)) {
    return res.status(400).json({
      success: false,
      error: '无效的标签ID',
    });
  }

  const {
    page = '1',
    limit = '10',
    status,
    authorId,
    categoryId,
    search,
    sortBy,
    sortOrder,
  } = req.query;

  const params: blogService.GetBlogsParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    status: status as blogService.BlogStatus,
    authorId: authorId ? parseInt(authorId as string) : undefined,
    categoryId: categoryId ? parseInt(categoryId as string) : undefined,
    tagId,
    search: search as string,
    sortBy: sortBy as any,
    sortOrder: sortOrder as any,
  };

  const result = await blogService.getBlogsByTag(tagId, params);

  res.status(200).json({
    success: true,
    data: result,
  });
});

