import { Router } from 'express';
import * as blogController from '../controllers/blog.controller';
import * as blogValidation from '../validations/blog.validation';
import { requireAuth } from '../middleware/auth';
import { validate } from '../middleware/validate';

const router = Router();

/**
 * @route POST /api/blogs
 * @desc 创建博客文章
 * @access Private
 */
router.post(
  '/',
  requireAuth,
  blogValidation.createBlogValidation,
  validate,
  blogController.createBlog
);

/**
 * @route GET /api/blogs
 * @desc 获取博客列表（支持分页、筛选、搜索）
 * @access Public
 */
router.get(
  '/',
  blogValidation.getBlogsValidation,
  validate,
  blogController.getBlogs
);

/**
 * @route GET /api/blogs/:id
 * @desc 获取单个博客详情
 * @access Public
 */
router.get(
  '/:id',
  blogValidation.blogIdValidation,
  validate,
  blogController.getBlog
);

/**
 * @route PUT /api/blogs/:id
 * @desc 更新博客文章
 * @access Private (作者或管理员)
 */
router.put(
  '/:id',
  requireAuth,
  blogValidation.updateBlogValidation,
  validate,
  blogController.updateBlog
);

/**
 * @route DELETE /api/blogs/:id
 * @desc 删除博客文章（软删除）
 * @access Private (作者或管理员)
 */
router.delete(
  '/:id',
  requireAuth,
  blogValidation.blogIdValidation,
  validate,
  blogController.deleteBlog
);

/**
 * @route POST /api/blogs/:id/publish
 * @desc 发布博客文章（将状态从草稿改为发布）
 * @access Private (作者或管理员)
 */
router.post(
  '/:id/publish',
  requireAuth,
  blogValidation.publishBlogValidation,
  validate,
  blogController.publishBlog
);

/**
 * @route GET /api/users/:userId/blogs
 * @desc 获取指定用户的博客列表
 * @access Private (用户只能查看自己的博客，管理员可以查看任何用户的博客)
 */
router.get(
  '/users/:userId/blogs',
  requireAuth,
  blogValidation.getUserBlogsValidation,
  validate,
  blogController.getUserBlogs
);

/**
 * @route GET /api/categories/:categoryId/blogs
 * @desc 按分类获取博客列表
 * @access Public
 */
router.get(
  '/categories/:categoryId/blogs',
  blogValidation.getBlogsByCategoryValidation,
  validate,
  blogController.getBlogsByCategory
);

/**
 * @route GET /api/tags/:tagId/blogs
 * @desc 按标签获取博客列表
 * @access Public
 */
router.get(
  '/tags/:tagId/blogs',
  blogValidation.getBlogsByTagValidation,
  validate,
  blogController.getBlogsByTag
);

export default router;

